function StateReplay() { const [from, setFrom] = useState('141'); const [to, setTo] = useState('142'); const [filter, setFilter] = useState('all'); const rows = [{ kind: 'changed', entity: 'Nashville capacity', previous: '480 units', next: '260 units', reason: 'Capacity reservation admitted', event: 'STATE_PROJECTED Ãƒâ€šÃ‚Â· evt-01938', time: '10:25:00 CDT', source: 'Control Plane projection', evidence: 'EV-2083 v2' }, { kind: 'changed', entity: 'Carrier commitment C-782', previous: 'Normal', next: 'At risk', reason: 'Capacity confirmation missing', event: 'KERNEL_DECIDED Ãƒâ€šÃ‚Â· evt-01942', time: '10:42:04 CDT', source: 'Institutional Kernel', evidence: 'Mandate MND-MEM-014' }]; const shown = filter === 'all' ? rows : rows.filter(row => row.kind === filter); return <div className="state-replay"><div className="state-replay-controls"><label>From version<select value={from} onChange={event => setFrom(event.target.value)}><option>140</option><option>141</option></select></label><label>To version<select value={to} onChange={event => setTo(event.target.value)}><option>142</option><option>143</option></select></label><button className="button secondary" onClick={() => setTo(to === '142' ? '143' : '142')}>Next replay step <ArrowRight size={14}/></button></div><div className="state-replay-filters" role="group" aria-label="State change filters">{['all','added','changed','removed'].map(item => <button key={item} className={filter === item ? 'active' : ''} onClick={() => setFilter(item)}>{item} <span>{item === 'changed' ? rows.length : item === 'all' ? rows.length : 0}</span></button>)}</div><div className="state-replay-meta"><span>Replay v{from} ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ v{to}</span><span>2 changes Ãƒâ€šÃ‚Â· 10:25ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“10:42 CDT</span><Badge tone="teal">State verified Ãƒâ€šÃ‚Â· simulated</Badge></div>{shown.length === 0 ? <EmptyState title="No changes in this filter" description="The selected state versions contain no matching simulated changes." /> : <div className="state-replay-table"><div className="state-replay-row state-replay-head"><span>Entity / resource</span><span>Previous value</span><span>New value</span><span>Reason and trigger</span><span>Recorded context</span><span /></div>{shown.map(row => <div className="state-replay-row" key={row.entity}><span><strong>{row.entity}</strong><small>{row.kind}</small></span><span>{row.previous}</span><span className="state-replay-new">{row.next}</span><span><strong>{row.reason}</strong><small>{row.event}</small></span><span><small>{row.time} Ãƒâ€šÃ‚Â· {row.source}</small><small>Evidence: {row.evidence}</small></span><button className="text-link" onClick={() => alert(`Simulated event inspector: ${row.event}`)}>Inspect event</button></div>)}</div>}<div className="state-replay-timeline"><span className="eyebrow">REPLAY STEPS</span><div><b className="active">v{from}</b><i/><b className="active">v{to}</b><i/><b>Outcome pending</b></div></div></div>; }

