export function IncidentQueue({ onOpen, empty }: { onOpen: (id: string) => void; empty: boolean }) {
  const [search, setSearch] = useState(''); const [filter, setFilter] = useState('All records');
  const matches = empty ? [] : incidents.filter(i => {
    const textMatches = `${i.id} ${i.title} ${i.site}`.toLowerCase().includes(search.toLowerCase());
    const filterMatches = filter === 'All records' || (filter === 'Active only' ? i.active : filter === 'Needs review' ? i.status === 'Review required' : i.severity === filter);
    return textMatches && filterMatches;
  });
  const activeCount = empty ? 0 : incidents.filter(i => i.active).length;
  return <>
    <div className="metrics-grid queue-metrics">
      <Metric label="Active incidents" value={String(activeCount)} detail="4 total incident records" />
      <Metric label="Commitments at risk" value={empty ? '0' : '7'} detail="From simulated operational records" tone="amber" />
      <Metric label="Modeled exposure" value={empty ? '$0' : '$287K'} detail="Range $250KÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“$325K Ãƒâ€šÃ‚Â· not a verified loss" />
      <button className="review-action-card" onClick={() => onOpen('INC-1042')} disabled={empty}>
        <span><ShieldCheck size={16} /> HUMAN REVIEW</span><strong>{empty ? 'No reviews required' : '1 review required'}</strong><small>{empty ? 'No active decision windows' : 'Memphis decision expires in 23 minutes'}</small><b>{empty ? 'Queue clear' : 'Review proposal'}<ArrowRight size={15} /></b>
      </button>
    </div>
    <Panel title="Work queue" action={<Badge tone="blue">READ-ONLY NETWORK</Badge>}>
      <div className="queue-toolbar"><label className="search-field"><Search size={16} /><input aria-label="Search incidents" placeholder="Search incident, site or IDÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦" value={search} onChange={e => setSearch(e.target.value)} /></label><select aria-label="Filter incidents" value={filter} onChange={e => setFilter(e.target.value)}>{['All records', 'Active only', 'Needs review', 'Critical', 'High', 'Moderate'].map(f => <option key={f}>{f}</option>)}</select><span className="record-count">{matches.length} incident records <i>Ãƒâ€šÃ‚Â·</i> {matches.filter(i => i.active).length} active</span></div>
      {matches.length ? <div className="table-scroll"><table className="incident-table"><thead><tr><th>Incident / site</th><th>Priority</th><th>Decision deadline</th><th>Modeled exposure</th><th>Cost of delay</th><th>State freshness</th><th>Next required action</th><th>Status</th><th><span className="sr-only">Open</span></th></tr></thead><tbody>{matches.map(i => <tr key={i.id} className={!i.active ? 'resolved-row' : ''}><td><button className="incident-link" onClick={() => onOpen(i.id)}><small>{i.id}</small><strong>{i.title}</strong><span>{i.site} Ãƒâ€šÃ‚Â· {i.commitments} commitments</span></button></td><td><Badge tone={i.severity === 'Critical' ? 'red' : i.severity === 'High' ? 'amber' : 'neutral'} dot>{i.severity}</Badge></td><td><strong>{i.decisionDeadline}</strong><small className={i.timeRemaining === '23 min' ? 'urgent-text' : ''}><Clock3 size={11} />{i.timeRemaining}</small></td><td><strong>{shortMoney(Math.round(i.exposure / 1000) * 1000)}</strong><small>modeled Ãƒâ€šÃ‚Â· unverified</small></td><td>{i.costOfDelay}</td><td><span className="freshness"><i className={i.active ? 'fresh' : 'closed'} />{i.stateFreshness}</span></td><td><button className="next-action" onClick={() => onOpen(i.id)}>{i.nextRequiredAction}<ChevronRight size={14} /></button></td><td><Badge tone={i.status === 'Outcome recorded' ? 'teal' : 'amber'}>{i.status}</Badge></td><td><button className="icon-button" aria-label={`Open ${i.id}`} onClick={() => onOpen(i.id)}><ArrowRight size={17} /></button></td></tr>)}</tbody></table></div> : <EmptyState title="No incidents to display" description={empty ? 'The empty-state fixture has no active incidents. Switch back to Live simulation to explore a populated queue.' : 'No incidents match these filters.'} action={!empty && <button className="button secondary" onClick={() => { setFilter('All records'); setSearch(''); }}>Clear filters</button>} />}
    </Panel>
  </>;
}
